func (this *Cryptocom) ParseTransaction(transaction any, optionalArgs ...any) any {
	//
	// fetchDeposits
	//
	//     {
	//         "currency": "BTC",
	//         "fee": 0,
	//         "create_time": 1688023659000,
	//         "id": "6201135",
	//         "update_time": 1688178509000,
	//         "amount": 0.00114571,
	//         "address": "1234fggxTSmJ3H4jaMQuWyEiLBzZdAbK6d",
	//         "status": "1",
	//         "txid": "f0ae4202b76eb999c301eccdde44dc639bee42d1fdd5974105286ca3393f6065/2"
	//     }
	//
	// fetchWithdrawals
	//
	//     {
	//         "currency": "BTC",
	//         "client_wid": "",
	//         "fee": 0.0005,
	//         "create_time": 1688613850000,
	//         "id": "5775977",
	//         "update_time": 1688613850000,
	//         "amount": 0.0005,
	//         "address": "1234NMEWbiF8ZkwUMxmfzMxi2A1MQ44bMn",
	//         "status": "1",
	//         "txid": "",
	//         "network_id": "BTC"
	//     }
	//
	// withdraw
	//
	//     {
	//         "id": 2220,
	//         "amount": 1,
	//         "fee": 0.0004,
	//         "symbol": "BTC",
	//         "address": "2NBqqD5GRJ8wHy1PYyCXTe9ke5226FhavBf",
	//         "client_wid": "my_withdrawal_002",
	//         "create_time":1607063412000
	//     }
	//
	currency := GetArg(optionalArgs, 0, nil)
	_ = currency
	var typeVar any = nil
	var rawStatus any = this.SafeString(transaction, "status")
	var status any = nil
	if IsTrue(InOp(transaction, "client_wid")) {
		typeVar = "withdrawal"
		status = this.ParseWithdrawalStatus(rawStatus)
	} else {
		typeVar = "deposit"
		status = this.ParseDepositStatus(rawStatus)
	}
	var addressString any = this.SafeString(transaction, "address")
	addresstagVariable := this.ParseAddress(addressString)
	address := GetValue(addresstagVariable, 0)
	tag := GetValue(addresstagVariable, 1)
	var currencyId any = this.SafeString(transaction, "currency")
	var code any = this.SafeCurrencyCode(currencyId, currency)
	var timestamp any = this.SafeInteger(transaction, "create_time")
	var feeCost any = this.SafeNumber(transaction, "fee")
	var fee any = nil
	if IsTrue(!IsEqual(feeCost, nil)) {
		fee = map[string]any{
			"currency": code,
			"cost":     feeCost,
		}
	}
	return map[string]any{
		"info":        transaction,
		"id":          this.SafeString(transaction, "id"),
		"txid":        this.SafeString(transaction, "txid"),
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"network":     nil,
		"address":     address,
		"addressTo":   address,
		"addressFrom": nil,
		"tag":         tag,
		"tagTo":       tag,
		"tagFrom":     nil,
		"type":        typeVar,
		"amount":      this.SafeNumber(transaction, "amount"),
		"currency":    code,
		"status":      status,
		"updated":     this.SafeInteger(transaction, "update_time"),
		"internal":    nil,
		"comment":     this.SafeString(transaction, "client_wid"),
		"fee":         fee,
	}
}
func (this *Cryptocom) CustomHandleMarginModeAndParams(methodName any, optionalArgs ...any) any {
	/**
	 * @ignore
	 * @method
	 * @description marginMode specified by params["marginMode"], this.options["marginMode"], this.options["defaultMarginMode"], params["margin"] = true or this.options["defaultType"] = 'margin'
	 * @param {object} [params] extra parameters specific to the exchange API endpoint
	 * @returns {Array} the marginMode in lowercase
	 */
	params := GetArg(optionalArgs, 0, map[string]any{})
	_ = params
	var defaultType any = this.SafeString(this.Options, "defaultType")
	var isMargin any = this.SafeBool(params, "margin", false)
	params = this.Omit(params, "margin")
	var marginMode any = nil
	marginModeparamsVariable := this.HandleMarginModeAndParams(methodName, params)
	marginMode = GetValue(marginModeparamsVariable, 0)
	params = GetValue(marginModeparamsVariable, 1)
	if IsTrue(!IsEqual(marginMode, nil)) {
		if IsTrue(!IsEqual(marginMode, "cross")) {
			panic(NotSupported(Add(this.Id, " only cross margin is supported")))
		}
	} else {
		if IsTrue(IsTrue((IsEqual(defaultType, "margin"))) || IsTrue((IsEqual(isMargin, true)))) {
			marginMode = "cross"
		}
	}
	return []any{marginMode, params}
}
func (this *Cryptocom) ParseDepositWithdrawFee(fee any, optionalArgs ...any) any {
	//
	//    {
	//        "full_name": "Alchemix",
	//        "default_network": "ETH",
	//        "network_list": [
	//          {
	//            "network_id": "ETH",
	//            "withdrawal_fee": "0.25000000",
	//            "withdraw_enabled": true,
	//            "min_withdrawal_amount": "0.5",
	//            "deposit_enabled": true,
	//            "confirmation_required": "0"
	//          }
	//        ]
	//    }
	//
	currency := GetArg(optionalArgs, 0, nil)
	_ = currency
	var networkList any = this.SafeList(fee, "network_list", []any{})
	var networkListLength int = GetArrayLength(networkList)
	var result map[string]any = map[string]any{
		"info": fee,
		"withdraw": map[string]any{
			"fee":        nil,
			"percentage": nil,
		},
		"deposit": map[string]any{
			"fee":        nil,
			"percentage": nil,
		},
		"networks": map[string]any{},
	}
	if IsTrue(!IsEqual(networkList, nil)) {
		for i := 0; IsLessThan(i, networkListLength); i++ {
			var networkInfo any = GetValue(networkList, i)
			var networkId any = this.SafeString(networkInfo, "network_id")
			var currencyCode any = this.SafeString(currency, "code")
			var networkCode any = this.NetworkIdToCode(networkId, currencyCode)
			if IsTrue(!IsEqual(networkCode, nil)) {
				AddElementToObject(GetValue(result, "networks"), networkCode, map[string]any{
					"deposit": map[string]any{
						"fee":        nil,
						"percentage": nil,
					},
					"withdraw": map[string]any{
						"fee":        this.SafeNumber(networkInfo, "withdrawal_fee"),
						"percentage": false,
					},
				})
			}
			if IsTrue(IsEqual(networkListLength, 1)) {
				AddElementToObject(GetValue(result, "withdraw"), "fee", this.SafeNumber(networkInfo, "withdrawal_fee"))
				AddElementToObject(GetValue(result, "withdraw"), "percentage", false)
			}
		}
	}
	return result
}

